import React from 'react';
import { marketStats } from '../data/mockData';
import { formatCompactFcfa } from '../lib/format';

interface StatItem {
  label: string;
  value: string;
  accent?: 'mint' | 'loss' | 'ink';
}

export default function MarketStatBar() {
  const stats = marketStats();

  const items: StatItem[] = [
    {
      label: 'Capitalisation totale',
      value: formatCompactFcfa(stats.mktCapBn * 1e9),
    },
    {
      label: 'Volume journalier',
      value: formatCompactFcfa(stats.dailyVolume),
    },
    {
      label: 'Nombre de valeurs',
      value: `${stats.total}`,
    },
    {
      label: 'Valeurs en hausse',
      value: `${stats.up}`,
      accent: 'mint',
    },
    {
      label: 'Valeurs en baisse',
      value: `${stats.down}`,
      accent: 'loss',
    },
  ];

  return (
    <div
      className="rounded-card bg-white border hairline shadow-card overflow-hidden"
      data-testid="market-stat-bar"
    >
      <div className="grid grid-cols-2 md:grid-cols-5 divide-x divide-y md:divide-y-0 hairline">
        {items.map((s) => (
          <div key={s.label} className="px-5 py-4">
            <div className="text-[11px] font-medium text-muted uppercase tracking-wider">
              {s.label}
            </div>
            <div
              className={`mt-1.5 text-[18px] font-bold num tracking-tight ${
                s.accent === 'mint'
                  ? 'text-mint-deep'
                  : s.accent === 'loss'
                    ? 'text-loss'
                    : 'text-ink'
              }`}
            >
              {s.value}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
